:= by
  have h1 : 1 / a + 1 / b = (a + b) / (a * b) := one_div_add_one_div ha hb
  rw [h1]
  have h2 : (a + b) * (a + b) / (a * b) ≥ 4 :=
    let h3 : (a + b)^2 / (a * b) ≥ 4 :=
      let h4 : (a + b)^2 ≥ 4 * a * b :=
        let h5 : (a + b)^2 - 4 * a * b ≥ 0 :=
          let h6 : a^2 + 2 * a * b + b^2 - 4 * a * b ≥ 0 :=
            let h7 : a^2 - 2 * a * b + b^2 ≥ 0 :=
              let h8 : (a - b)^2 ≥ 0 :=
                Real.pow_two_nonneg (a - b)
              exact h8
            exact h7
          exact h6
        exact h4
      exact h3
  exact h2
